"""Study 3 as a design: dinov2-large and resnet-18, each a branch of its own,
joined into one linear head. It follows notebook 04's `fusion_architecture.py`,
with the encoders of study 3 and the plain `Linear` head it trained (notebook 06).

Read it in atlas: the shape on every arrow, where the two branches join, and where the
`project` option would add a projection per branch.

    atlas-code-nightly view notebooks/1_representation_and_head/exercises

Run it from the root of the course repository to see the shape after every stage:

    uv run notebooks/1_representation_and_head/exercises/fusion_design.py
"""

from dataclasses import dataclass

import torch
from beartype import beartype
from jaxtyping import Float, jaxtyped
from torch import Tensor, nn
from vectormesh.components import Concatenate2D, Parallel, Projection
from vectormesh.design import Design, option


@dataclass(frozen=True)
class Config:
    """The choices of the design. Study 3 trained it without projections."""

    shared_dim: int = 128  # each branch projects to this width before the join
    project: bool = False  # a projection per branch before the join


class Fusion(nn.Module):
    """Two streams, one per encoder, joined into one linear head. The model takes
    the pair a joined loader gives. Each stage is a method whose signature states the
    shape it takes and the shape it gives; `@jaxtyped` checks it on every call."""

    projections: Parallel

    def __init__(
        self, config: Config, dino_dim: int, resnet_dim: int, n_classes: int
    ) -> None:
        super().__init__()
        self.config = config
        self.dino_dim = dino_dim
        self.resnet_dim = resnet_dim
        self.shared_dim = config.shared_dim
        self.joined_dim = (
            2 * config.shared_dim if config.project else dino_dim + resnet_dim
        )
        self.n_classes = n_classes
        # an optional stage's layers exist only in the subgraph that uses them
        if config.project:
            self.projections = Parallel(
                [
                    Projection(dino_dim, config.shared_dim),
                    Projection(resnet_dim, config.shared_dim),
                ]
            )
        self.concatenate = Concatenate2D()
        self.head = nn.Linear(self.joined_dim, n_classes)

    @option("project")
    @jaxtyped(typechecker=beartype)
    def project(
        self,
        streams: tuple[
            Float[Tensor, "batch {self.dino_dim}"],
            Float[Tensor, "batch {self.resnet_dim}"],
        ],
    ) -> tuple[
        Float[Tensor, "batch {self.shared_dim}"],
        Float[Tensor, "batch {self.shared_dim}"],
    ]:
        return self.projections(streams)

    @jaxtyped(typechecker=beartype)
    def join(
        self, streams: tuple[Float[Tensor, "batch _"], Float[Tensor, "batch _"]]
    ) -> Float[Tensor, "batch {self.joined_dim}"]:
        return self.concatenate(streams)

    @jaxtyped(typechecker=beartype)
    def classify(
        self, joined: Float[Tensor, "batch {self.joined_dim}"]
    ) -> Float[Tensor, "batch {self.n_classes}"]:
        return self.head(joined)

    @jaxtyped(typechecker=beartype)
    def forward(
        self,
        streams: tuple[
            Float[Tensor, "batch {self.dino_dim}"],
            Float[Tensor, "batch {self.resnet_dim}"],
        ],
    ) -> Float[Tensor, "batch {self.n_classes}"]:
        if self.config.project:
            streams = self.project(streams)
        joined = self.join(streams)
        return self.classify(joined)


# The model and the config that switches its option, as a search reads them.
DESIGN = Design(Fusion, Config)


if __name__ == "__main__":
    # dinov2-large is 1024 wide, resnet-18 is 512, and DTD has 47 textures; two rows
    # trace every shape
    DESIGN.show(
        (torch.randn(2, 1024), torch.randn(2, 512)),
        dino_dim=1024,
        resnet_dim=512,
        n_classes=47,
    )
